window.DOC_EXCERPTS = {"资料分析": {"pointer": "📌 对应权威文字资料：<code>miss-mumu/developer2gwy/doc/行测知识模块清单.md#资料分析</code> · <code>Issue #13 行测破题四步流</code> · <code>zhangxiangliang/posts/资料分析/资料分析.md</code>", "repoUrl": "https://github.com/miss-mumu/developer2gwy/blob/main/doc/%E8%A1%8C%E6%B5%8B%E7%9F%A5%E8%AF%86%E6%A8%A1%E5%9D%97%E6%B8%85%E5%8D%95.md", "html": "\n<div class=\"excerpt-grid\">\n  <div class=\"excerpt-card\">\n    <div class=\"excerpt-tag\">📄 摘自 miss-mumu/developer2gwy · 《行测知识模块清单.md》&amp; Issue #13</div>\n    <h4>一、资料分析通关核对清单与高分破题流</h4>\n    <p><strong>【D2G 高分选手做题流】</strong>：行测拿高分的共同点是——<strong>先看清提问（确定考察时间、主体与考点公式） → 扫一眼选项（形成量级与差距预期，确定截两位还是截三位） → 回材料定位数据（调用对应速算技巧） → 直接选出答案</strong>，切忌从头到尾精读材料浪费时间。</p>\n    <div class=\"excerpt-checklist\">\n      <span>☑ 方法技巧：速算技巧（截位直除/百化分/尾数法）、快速找数（文字圈中心词/表图看标题横纵标目单位备注）</span>\n      <span>☑ 四大核心母题：基期与现期、增长率（一般/间隔/年均/混合）、增长量（计算与大大则大比较）、比重/平均数/倍数（现期/基期/两期升降与差值）</span>\n    </div>\n  </div>\n  <div class=\"excerpt-card\">\n    <div class=\"excerpt-tag\">📄 摘自 zhangxiangliang/civil-service-exam · 《posts/资料分析/资料分析.md》</div>\n    <h4>二、速算四大实战技法与高频分数百化分对照表</h4>\n    <ul>\n      <li><strong>尾数法（加减乘精确计算）</strong>：选项末位或末两位不同且精度与材料一致时，直接计算尾数比对答案，注意借位与小数点位数对齐。</li>\n      <li><strong>首数法与截位直除</strong>：一步除法只截分母，多步乘除分子分母同截；选项首位不同截两位，首位相同且次位差小于等于首位时截三位。</li>\n      <li><strong>有效数字近似与数字替换法（百化分必背表）</strong>：将不易计算的小数/百分数直接替换为分数：</li>\n    </ul>\n    <table class=\"mini-ref-table\">\n      <thead>\n        <tr><th>百分数/小数</th><th>对应分数</th><th>百分数/小数</th><th>对应分数</th><th>百分数/小数</th><th>对应分数</th></tr>\n      </thead>\n      <tbody>\n        <tr><td>50% (0.5)</td><td>1/2</td><td>33.3% / 66.7%</td><td>1/3 · 2/3</td><td>25% / 75%</td><td>1/4 · 3/4</td></tr>\n        <tr><td>20% / 40% / 60%</td><td>1/5 · 2/5 · 3/5</td><td>16.7% (0.167)</td><td>1/6</td><td>14.3% / 28.6%</td><td>1/7 · 2/7</td></tr>\n        <tr><td>12.5% / 37.5% / 62.5%</td><td>1/8 · 3/8 · 5/8</td><td>11.1% / 22.2%</td><td>1/9 · 2/9</td><td>9.1% / 18.2%</td><td>1/11 · 2/11</td></tr>\n        <tr><td>8.3% / 7.7% / 7.1%</td><td>1/12 · 1/13 · 1/14</td><td>6.7% / 6.25%</td><td>1/15 · 1/16</td><td>5.9% / 5.6% / 5.3%</td><td>1/17 · 1/18 · 1/19</td></tr>\n      </tbody>\n    </table>\n  </div>\n</div>\n"}, "判断推理_图推": {"pointer": "📌 对应权威文字资料：<code>zhangxiangliang/posts/判断推理/图形推理.md</code> · <code>kuriv/行测/判断推理/图形推理</code> · <code>developer2gwy/doc/行测知识模块清单.md</code>", "repoUrl": "https://github.com/zhangxiangliang/civil-service-exam/blob/master/posts/%E5%88%A4%E6%96%AD%E6%8E%A8%E7%90%86/%E5%9B%BE%E5%BD%A2%E6%8E%A8%E7%90%86.md", "html": "\n<div class=\"excerpt-grid\">\n  <div class=\"excerpt-card\">\n    <div class=\"excerpt-tag\">📄 摘自 zhangxiangliang/civil-service-exam · 《posts/判断推理/图形推理.md》</div>\n    <h4>一、图形推理四大常考题型与考场破题铁律</h4>\n    <ul>\n      <li><strong>类比型图推</strong>：给出两组各三个图形，根据第一组图形的构成或几何转化规律推导第二组。</li>\n      <li><strong>顺推型图推</strong>：给出一排连续图形，重点观察<strong>共同特征、连续递变、奇偶间隔排序、中间位置对称</strong>。</li>\n      <li><strong>九宫格图推</strong>：优先按“行”或“列”分为三组对比观察，复杂题考虑“米”字型或外圈环形规律。</li>\n      <li><strong>空间重构（六面体/立体拼合）</strong>：利用相对面排除（同行同列隔一个、Z字两端）+ 相邻面公共边/画边法（找唯一面顶点顺时针画边比对选项）。</li>\n      <li><strong>⚡ 考场实战思路</strong>：多道图推题可对比观察（同一套卷极少重复考同一细分规律）；<strong>先看整体元素组成定大类（相同看位置→相似看样式→凌乱先属性后数量），数点、线、面较费时放后面验证</strong>。</li>\n    </ul>\n  </div>\n  <div class=\"excerpt-card\">\n    <div class=\"excerpt-tag\">📄 摘自 kuriv/civil-service-exam · 《图形推理核心特征信号表》</div>\n    <h4>二、图推秒杀特征图信号对照表</h4>\n    <table class=\"mini-ref-table\">\n      <thead>\n        <tr><th>题干典型图形特征</th><th>第一反应考点方向</th><th>高频细化考法</th></tr>\n      </thead>\n      <tbody>\n        <tr><td>元素组成完全相同</td><td>位置规律（平移/旋转/翻转）</td><td>内外圈分开平移、时针法区分旋转与翻转</td></tr>\n        <tr><td>线条重复出现、黑白块数量不同</td><td>样式规律（加减同异/黑白运算）</td><td>先看外框与内部线条求同求异；黑白块优先验证黑+白</td></tr>\n        <tr><td>图形规整美观、等腰元素多</td><td>属性规律（对称/曲直/开闭）</td><td>对称轴数量、对称轴旋转角度、对称轴与原图点线面关系</td></tr>\n        <tr><td>窟窿（封闭空白区）明显</td><td>数量规律 · 数面</td><td>最大面/最小面的形状、属性（是否中心对称）、与外框相似</td></tr>\n        <tr><td>五角星、“日/田”变形、切圆、出头线</td><td>数量规律 · 笔画数与线</td><td>奇点数=0或2为一笔画；多笔画数 = 奇点数 ÷ 2；平行线组数</td></tr>\n      </tbody>\n    </table>\n  </div>\n</div>\n"}, "判断推理_逻辑": {"pointer": "📌 对应权威文字资料：<code>miss-mumu/developer2gwy/doc/行测知识模块清单.md#逻辑判断</code> · <code>zhangxiangliang/posts/判断推理/定义判断.md &amp; 类比推理.md</code> · <code>kuriv/逻辑判断</code>", "repoUrl": "https://github.com/zhangxiangliang/civil-service-exam/blob/master/posts/%E5%88%A4%E6%96%AD%E6%8E%A8%E7%90%86/%E5%AE%9A%E4%B9%89%E5%88%A4%E6%96%AD.md", "html": "\n<div class=\"excerpt-grid\">\n  <div class=\"excerpt-card\">\n    <div class=\"excerpt-tag\">📄 摘自 zhangxiangliang/civil-service-exam · 《定义判断.md》&amp;《类比推理.md》</div>\n    <h4>一、定义判断“种差+属”拆解法与类比推理关系谱</h4>\n    <ul>\n      <li><strong>定义判断底层结构</strong>：<code>被定义项 = 种差 + 临近属概念</code>（如“人是能制造和使用工具进行劳动的动物”，属概念是“动物”，种差是“制造和使用工具”）。</li>\n      <li><strong>提取要件六字诀</strong>：快速圈出被定义项中的<strong>主体、客体、目的（为了/确保）、原因（由于/出于）、条件（以…为前提）、手段（通过/利用）、结果（导致/从而）</strong>作为排除依据；读不懂定义时直接<strong>对比选项找异类</strong>。</li>\n      <li><strong>类比推理五大关系</strong>：① 概念逻辑关系（全同、种属 vs 组成、矛盾 vs 反对、交叉）；② 词义关系（近义、反义、比喻象征义）；③ 语法关系（主谓、动宾、偏正）；④ 条件关系（因果、顺承、目的、必要条件）；⑤ 常识对应（功能、原材料、职业场所、作品人物）。</li>\n    </ul>\n  </div>\n  <div class=\"excerpt-card\">\n    <div class=\"excerpt-tag\">📄 摘自 developer2gwy &amp; kuriv · 《逻辑判断形式推理与论证秒杀清单》</div>\n    <h4>二、翻译推理口诀与削弱加强力度排序</h4>\n    <ul>\n      <li><strong>形式逻辑必背</strong>：前推后（如果…就…/只要…就…/所有…都…）；后推前（只有…才…/不…不…/除非A否则不B → B推A）；<strong>逆否定理</strong>（肯前必肯后，否后必否前，否前肯后不确定）；<strong>摩根定律</strong>：<code>-(A且B) = -A 或 -B</code>，<code>-(A或B) = -A 且 -B</code>。</li>\n      <li><strong>加强论证力度排序</strong>：<strong>搭桥（论据与论点概念不一致，直接建立联系） &gt; 补充必要条件（没它论点必不成立） &gt; 解释说明 &gt; 举例支持</strong>。</li>\n      <li><strong>削弱论证力度排序</strong>：<strong>直接否定论点 &gt; 拆桥/因果倒置 &gt; 否定论据 &gt; 另有他因</strong>。</li>\n      <li><strong>日常结论“三不选两慎选”</strong>：逻辑错误、无中生有、偷换概念必不选；含绝对化词（一定/必须/所有/唯一）或无依据比较词（更/越来越）慎选。</li>\n    </ul>\n  </div>\n</div>\n"}, "言语理解": {"pointer": "📌 对应权威文字资料：<code>zhangxiangliang/posts/言语理解与表达/词义辨析.md &amp; 语句连贯.md &amp; 词汇积累.md</code> · <code>miss-mumu/developer2gwy/doc/行测知识模块清单.md#言语理解</code>", "repoUrl": "https://github.com/zhangxiangliang/civil-service-exam/blob/master/posts/%E8%A8%80%E8%AF%AD%E7%90%86%E8%A7%A3%E4%B8%8E%E8%A1%A8%E8%BE%BE/%E8%AF%8D%E6%B1%87%E7%A7%AF%E7%B4%AF.md", "html": "\n<div class=\"excerpt-grid\">\n  <div class=\"excerpt-card\">\n    <div class=\"excerpt-tag\">📄 摘自 zhangxiangliang/civil-service-exam · 《词义辨析.md》&amp;《语句连贯.md》</div>\n    <h4>一、选词填空“理性义+色彩义”双维破题与语句连贯技法</h4>\n    <ul>\n      <li><strong>词义辨析两步法</strong>：① 先用<strong>理性义</strong>辨析词义的侧重点、所指范围与轻重程度（如“漫延”专指水铺满，“蔓延”指植物生长、火势扩张或抽象事物发展）；② 再用<strong>色彩义</strong>判断感情色彩（褒义/贬义/中性）与语体色彩（公文庄重规范 vs 口语通俗）。</li>\n      <li><strong>语句排序三步走</strong>：先看选项首尾句排除（指代词“这/那/其”、关联词后半段“但/却/而且”不能做首句）→ 抓关联词搭档、指代词、顶真法（前句尾字作后句首字）、时间空间逻辑顺序定捆绑 → 代入通读验证。</li>\n      <li><strong>语句填空六原则</strong>：话题统一（主语一致）、意境协调、重点突出、句式一致（排比/对偶）、前后照应（尤其注意<strong>分号表并列、冒号和破折号表解释说明</strong>）。</li>\n    </ul>\n  </div>\n  <div class=\"excerpt-card\">\n    <div class=\"excerpt-tag\">📄 摘自 zhangxiangliang/posts/言语理解与表达/词汇积累.md（高频易混实词与成语原文）</div>\n    <h4>二、公考高频易混实词与易错成语精粹（节选）</h4>\n    <div class=\"vocab-chips\">\n      <div class=\"v-item\"><strong>力行 vs 厉行</strong>：“力行”侧重亲自实践（身体力行）；“厉行”侧重严格执行（厉行节约）。</div>\n      <div class=\"v-item\"><strong>截止 vs 截至</strong>：“截止”表停止，后不能直接带时间宾语（只能说“截止到5月”）；“截至”可直接带时间（“截至5月”）。</div>\n      <div class=\"v-item\"><strong>推脱 vs 推托</strong>：“推脱”指逃避推卸（推脱责任）；“推托”指借故拒绝他人请求（推托不去）。</div>\n      <div class=\"v-item\"><strong>约束 vs 制约</strong>：“约束”多对自己或内部规章；“制约”指外部条件限制对方（甲制约乙）。</div>\n      <div class=\"v-item\"><strong>首当其冲 vs 首屈一指</strong>：“首当其冲”指最先受到攻击或遭遇灾难（并非“第一名”！）；“首屈一指”才表示位居第一。</div>\n      <div class=\"v-item\"><strong>望尘莫及 vs 鞭长莫及</strong>：“望尘莫及”指远远落后赶不上；“鞭长莫及”指距离太远管辖不到（不表落后）。</div>\n      <div class=\"v-item\"><strong>相提并论 vs 同日而语</strong>：“相提并论”用于不同事物横向对比；“同日而语”用于同一事物不同时期的纵向对比。</div>\n      <div class=\"v-item\"><strong>积重难返 vs 根深蒂固</strong>：“积重难返”指长期形成的不良习俗弊端难改；“根深蒂固”指思想观念基础深厚难动摇。</div>\n    </div>\n  </div>\n</div>\n"}, "数量关系": {"pointer": "📌 对应权威文字资料：<code>miss-mumu/developer2gwy/doc/行测知识模块清单.md#数量关系</code> · <code>zhangxiangliang/posts/数量关系/数学运算.md &amp; 数字推理.md</code> · <code>kuriv/数量关系</code>", "repoUrl": "https://github.com/miss-mumu/developer2gwy/blob/main/doc/%E8%A1%8C%E6%B5%8B%E7%9F%A5%E8%AF%86%E6%A8%A1%E5%9D%97%E6%B8%85%E5%8D%95.md", "html": "\n<div class=\"excerpt-grid\">\n  <div class=\"excerpt-card\">\n    <div class=\"excerpt-tag\">📄 摘自 miss-mumu/developer2gwy &amp; zhangxiangliang · 《数量关系考场取舍与核心公式》</div>\n    <h4>一、数量关系考场实战策略（撑死胆大，敢于取舍）</h4>\n    <p><strong>【D2G &amp; zhangxiangliang 实战共识】</strong>：行测 120 分钟平均每题不到 50 秒，数量关系绝不能从头硬算到尾！考场上用 <strong>12—15 分钟优先挑出 5—6 道特征明显的母题（工程赋值、给定比例倍比、基础经济利润、容斥公式、和定最值）</strong>稳拿满分，其余复杂题结合<strong>倍数特性、奇偶尾数排除后统一蒙出现最少的选项</strong>。</p>\n    <ul>\n      <li><strong>和差倍比核心式</strong>：<code>和 ÷ (倍数 + 1) = 小数</code>；<code>差 ÷ (倍数 - 1) = 小数</code>；<code>(和 + 差) ÷ 2 = 大数</code>。</li>\n      <li><strong>比例倍数秒杀</strong>：若 <code>A : B = m : n</code>（m与n互质），则 A 必为 m 的倍数，B 必为 n 的倍数，<code>A ± B</code> 必为 <code>m ± n</code> 的倍数。</li>\n    </ul>\n  </div>\n  <div class=\"excerpt-card\">\n    <div class=\"excerpt-tag\">📄 摘自 zhangxiangliang/mindnode &amp; kuriv/数量关系 · 《高频题型秒杀公式卡》</div>\n    <h4>二、六大必拿分母题公式速查</h4>\n    <ul>\n      <li><strong>工程问题</strong>：① 给多个完工时间 → 先赋工作总量为完工时间的最小公倍数，再求效率；② 给效率比 → 直接按比例赋效率；③ 牛吃草/注排水：注水效率为正、排水效率为负。</li>\n      <li><strong>行程问题</strong>：等距离平均速度 <code>v = 2v₁v₂ ÷ (v₁ + v₂)</code>；流水行船 <code>顺水 = 船 + 水</code>、<code>逆水 = 船 - 水</code>；直线两端出发第 n 次相遇总路程 <code>(2n - 1)S = (v₁ + v₂)t</code>。</li>\n      <li><strong>排列组合与错位重排</strong>：相邻用捆绑法，不相邻用插空法，相同元素分堆至少1个用隔板法 <code>C(n-1, m-1)</code>；<strong>错位重排必背数</strong>：<code>D₁=0, D₂=1, D₃=2, D₄=9, D₅=44</code>。</li>\n      <li><strong>几何尺度性质</strong>：边长扩大 n 倍，周长变为 n 倍，面积变为 n² 倍，体积变为 n³ 倍；周长一定时越趋近于圆面积越大。</li>\n    </ul>\n  </div>\n</div>\n"}, "申论": {"pointer": "📌 对应权威文字资料：<code>miss-mumu/developer2gwy/doc/申论知识模块清单.md</code> · <code>Issue #36 理工科/零基础写申论难吗？</code> · <code>zhangxiangliang/posts/公共基础知识/公文.md</code>", "repoUrl": "https://github.com/miss-mumu/developer2gwy/blob/main/doc/%E7%94%B3%E8%AE%BA%E7%9F%A5%E8%AF%86%E6%A8%A1%E5%9D%97%E6%B8%85%E5%8D%97.md", "html": "\n<div class=\"excerpt-grid\">\n  <div class=\"excerpt-card\">\n    <div class=\"excerpt-tag\">📄 摘自 miss-mumu/developer2gwy · 《申论知识模块清单.md》&amp; Issue #36 原文</div>\n    <h4>一、D2G 揭秘申论阅卷真相：申论不是比文采，而是“按点给分”！</h4>\n    <p><strong>【原文核心摘录】</strong>：“申论的考试虽说是主观部分，但也是有迹可循的。对于<strong>单一题、综合题、公文题，大多都是按点给分</strong>，写到要点关键词就给分，写漏写偏不倒扣分！其中 <strong>70% 以上的答案要点直接来自材料摘抄与归纳</strong>；公文题就是<strong>格式 + 摘抄 + 逻辑组织</strong>；大作文也是在材料的框架下提出论点围绕论证，只要结构完整、字迹清晰，保底 25 分以上。也就是说，<strong>申论 100 分里至少有 70 分是有明确标准、能通过科学训练稳稳拿下的</strong>！”</p>\n    <ul>\n      <li><strong>核心能力转化</strong>：养成<strong>“见词、读句、识意”</strong>的习惯——把材料中的具体案例、口语俗语翻译成“是什么（问题/表现）、为什么（原因/影响）、怎么办（对策/举措）”的规范书面语。</li>\n    </ul>\n  </div>\n  <div class=\"excerpt-card\">\n    <div class=\"excerpt-tag\">📄 摘自 kuriv/申论 &amp; zhangxiangliang/posts/公共基础知识/公文.md</div>\n    <h4>二、申论四大题型采分信号词与公文格式铁律</h4>\n    <ul>\n      <li><strong>材料采分提示词</strong>：① <strong>问题词</strong>（不到位/不健全/缺失/流失/薄弱/瓶颈）；② <strong>影响词</strong>（有利于/促进了/倒逼/损害了/制约了）；③ <strong>对策词</strong>（建立/健全/统筹/规范/整治/扶持/应当/务必）。</li>\n      <li><strong>公文文种选型口诀（zhangxiangliang）</strong>：<code>国内外事用公告，一定范围用通告；表批情况用通报，执行转批用请示；提出见解用意见，不相隶属请用函</code>。</li>\n      <li><strong>应用文格式对应表（kuriv）</strong>：\n        <br/>· <strong>有标题 + 有称谓 + 有落款</strong>：公开信、倡议书、宣传稿；\n        <br/>· <strong>有标题 + 有称谓 + 无落款</strong>：发言稿、讲话稿、讲解稿；\n        <br/>· <strong>有标题 + 无称谓 + 无落款</strong>：调研报告、整改方案、指导意见、短评/时评、工作简报；\n        <br/>· <strong>无格式（直接分条写正文）</strong>：题干明确要求“写一份内容要点/提纲/不要求格式”。</li>\n    </ul>\n  </div>\n</div>\n"}, "常识政治": {"pointer": "📌 对应权威文字资料：<code>miss-mumu/developer2gwy/issues/14 常识怎么准备好？</code> · <code>zhangxiangliang/posts/公共基础知识/政治哲学.md &amp; 国情概况.md &amp; 人文历史.md &amp; 高新科技.md</code>", "repoUrl": "https://github.com/miss-mumu/developer2gwy/issues/14", "html": "\n<div class=\"excerpt-grid\">\n  <div class=\"excerpt-card\">\n    <div class=\"excerpt-tag\">📄 摘自 miss-mumu/developer2gwy · Issue #14《常识怎么准备好？》原文</div>\n    <h4>一、D2G 常识备考“收益比”法则（拒绝眉毛胡子一把抓）</h4>\n    <p><strong>【原文核心摘录】</strong>：“准备常识模块一定要有<strong>投入产出收益比思维</strong>，切勿什么都背！按考察概率与题量从高到低排序，优先抓牢前四项：”</p>\n    <ol>\n      <li><strong>第一优先级 · 时政与政治理论</strong>：考前半年至一年的重大会议文件、新修订法律法规、重大科技成就（国考省考占比最高，且与申论、面试直接互通）。</li>\n      <li><strong>第二优先级 · 法律与经济</strong>：宪法、行政法（处罚/复议/诉讼）、民法典、刑法生活案例；财政政策与货币政策、常见宏观经济指标。</li>\n      <li><strong>第三优先级 · 文史与科技地理</strong>：党史重大会议、中国古代制度与朝代脉络、二十四节气、中国地理三级阶梯与邻国、物理化学生物生活常识。</li>\n    </ol>\n  </div>\n  <div class=\"excerpt-card\">\n    <div class=\"excerpt-tag\">📄 摘自 zhangxiangliang/civil-service-exam · 《政治哲学.md》《国情概况.md》《人文历史.md》</div>\n    <h4>二、高频必背口诀与常识锦囊（原文精粹）</h4>\n    <ul>\n      <li><strong>唯物辩证法“二三六”框架</strong>：两大特征（普遍联系、永恒发展）；三大规律（<strong>对立统一规律是核心和实质</strong>、质量互变规律、否定之否定规律）；六对范畴（整体与部分、原因与结果、现象与本质、偶然与必然、可能与现实、内容与形式）。</li>\n      <li><strong>我国 14 个陆上邻国口诀</strong>：<code>朝俄蒙哈吉塔阿，巴印尼泊和不丹，缅甸老挝接越南，陆上邻国依次连</code>；三大平原（东北、华北、长江中下游），四大盆地（塔里木、准噶尔、柴达木、四川），五大淡水湖（鄱阳湖、洞庭湖、太湖、洪泽湖、巢湖）。</li>\n      <li><strong>二十四节气歌</strong>：<code>春雨惊春清谷天，夏满芒夏暑相连，秋处露秋寒霜降，冬雪雪冬小大寒</code>。</li>\n    </ul>\n  </div>\n</div>\n"}, "复盘模考": {"pointer": "📌 对应权威文字资料：<code>miss-mumu/developer2gwy/issues/13 行测65-80分瓶颈突破</code> · <code>Issue #33 考公学习如何总结和反思</code> · <code>Issue #9/#34 在职碎片时间高效备考</code>", "repoUrl": "https://github.com/miss-mumu/developer2gwy/issues/13", "html": "\n<div class=\"excerpt-grid\">\n  <div class=\"excerpt-card\">\n    <div class=\"excerpt-tag\">📄 摘自 miss-mumu/developer2gwy · 《行测知识模块清单.md》&amp; Issue #13 原文</div>\n    <h4>一、行测 60 / 70 / 80 分四大境界诊断与瓶颈突破指南</h4>\n    <table class=\"mini-ref-table\">\n      <thead>\n        <tr><th>分数段</th><th>当前状态诊断（D2G 原文）</th><th>核心突破处方</th></tr>\n      </thead>\n      <tbody>\n        <tr><td>&lt; 60 分</td><td>模块学习不细致、刷题不系统，缺乏整体认知与技巧</td><td>扎好马步完整过一遍基础，系统刷题不留盲区</td></tr>\n        <tr><td>60 ~ 70 分</td><td>基础过完但熟练度不够，<strong>做题效率与正确率失衡</strong>（做不完卷子）</td><td>固化涂卡与取舍节奏，重点突破优势模块速度</td></tr>\n        <tr><td>70 ~ 80 分</td><td>体系扎实、题量达标，仅在偏题怪题或个别模块波动</td><td>错题二次归因总结，打磨“看提问→扫选项→找支撑”题感</td></tr>\n      </tbody>\n    </table>\n  </div>\n  <div class=\"excerpt-card\">\n    <div class=\"excerpt-tag\">📄 摘自 miss-mumu/developer2gwy · Issue #33《考公学习如何总结和反思》&amp; Issue #34</div>\n    <h4>二、D2G 错题本记录六要素与“以教促学”复盘法</h4>\n    <ul>\n      <li><strong>笔记本/错题本必须记什么</strong>：① 重要核心公式；② <strong>题型的判断要素（信号词）</strong>；③ 细节易错坑点；④ <strong>每学完一个模块手绘一张思维导图</strong>；⑤ 典型错题的思维断点；⑥ 阶段模考时间分配感悟。</li>\n      <li><strong>“以教促学”自检法</strong>：合上讲义和笔记，把今天学的题型判定规则、推导步骤通俗地讲给自己听——凡是讲卡壳的地方，就是考场上会掉坑的伪掌握点！</li>\n      <li><strong>碎片时间黄金法则（Issue #34）</strong>：<strong>“碎片化学习的本质，不是为了把系统课拆碎，而是用通勤/午休处理背诵、时政和错题回顾，从而为晚间挤出整块系统刷题与套卷实战的时间！”</strong></li>\n    </ul>\n  </div>\n</div>\n"}};

window.LIBRARY_ARTICLES = [{"id": "d2g_xingce", "cat": "D2G 备考核心清单", "title": "1. 行测知识模块全景清单与 60/70/80 分进阶指南", "source": "miss-mumu/developer2gwy/doc/行测知识模块清单.md & Issue #13", "url": "https://github.com/miss-mumu/developer2gwy/blob/main/doc/%E8%A1%8C%E6%B5%8B%E7%9F%A5%E8%AF%86%E6%A8%A1%E5%9D%97%E6%B8%85%E5%8D%95.md", "content": "\n<h3>一、行测考察的本质：做题效率与正确率的动态平衡</h3>\n<p>行测考试虽然众说纷纭，但其考察的本质就是应试学习能力，简单来讲就是<strong>做题能力</strong>。D2G 团队多位上岸成员复盘发现：<strong>60 分、70 分、80 分各是一道坎</strong>：</p>\n<table class=\"mini-ref-table\">\n  <thead>\n    <tr><th>分数境界</th><th>能力画像（工程师对标）</th><th>D2G 针对性提分建议</th></tr>\n  </thead>\n  <tbody>\n    <tr><td><strong>小于 60 分</strong></td><td>初级水平：模块学习有遗漏，刷题不系统，对行测缺乏整体认识与做题技巧，上岸随缘。</td><td>打好基础，完完整整过一遍基础知识；对照模块清单系统刷题，不遗漏任一核心考点。</td></tr>\n    <tr><td><strong>60 至 70 分</strong></td><td>中级水平：过了一遍基础但熟练度不足，做题效率不高，常因时间不够手忙脚乱，得分看状态。</td><td>专项刷题+错题总结+严格限时训练，优先把资料分析、判断推理、言语三大块正确率稳定在 75%+。</td></tr>\n    <tr><td><strong>70 至 80 分</strong></td><td>高级水平：系统深入学完刷完，得分稳定，仅在偏题怪题或时间分配小幅波动，上岸率极大。</td><td>刷题→总结→再刷题→再总结，打磨“看提问→扫选项→略读题干找支撑→秒选”的高阶题感。</td></tr>\n    <tr><td><strong>80 分以上</strong></td><td>资深水平：看清提问与选项就大致知道答案，看题干只是验证设想，只要面试不拉胯上岸率超 99%。</td><td>定期套卷保温，维持考场兴奋度与肌肉记忆。</td></tr>\n  </tbody>\n</table>\n\n<h3>二、行测五大模块破题标准动作（Issue #13 核心提炼）</h3>\n<ul>\n  <li><strong>资料分析</strong>：看提问（确定时间、主体与考点公式） → 看选项（判断差距定截位位数） → 找数据（调用截位直除/百化分/混合居中口诀） → 选答案。</li>\n  <li><strong>判断推理</strong>：看提问（选是/选非、加强/削弱） → 扫选项（排除明显偏离项） → 读题干（找论点论据或提取定义要件/图形特征） → 选答案。</li>\n  <li><strong>言语理解</strong>：看提问（中心理解/细节/接语/填空） → 扫选项（排除无中生有与极端绝对项） → 读题干（抓转折/因果/对策主题词与语境对应） → 选答案。</li>\n  <li><strong>数量关系</strong>：看提问（识别工程/行程/经济/最值/容斥母题） → 看选项（观察奇偶、倍数、尾数特征） → 列式或代入排除 → 选答案。</li>\n  <li><strong>常识判断</strong>：看提问（调用时政/法律/经济/文史储备） → 扫选项（排除绝对化与违背常理项） → 比对题干关键词 → 选答案。</li>\n</ul>\n\n<h3>三、行测全考点自查清单（学完一项勾选一项）</h3>\n<ul>\n  <li><strong>1. 资料分析</strong>：速算技巧（截位直除/尾数/百化分） · 快速找数 · 基期与现期 · 一般增长率/间隔增长率/年均增长率/混合增长率 · 增长量计算与比较 · 现期比重/基期比重/两期比重升降与差值 · 平均数与平均数增长率 · 倍数与翻番 · 综合分析。</li>\n  <li><strong>2. 判断推理</strong>：图形推理（平面位置/样式/属性/数量/一笔画/空间重构六面体/三视图/截面图/立体拼合） · 类比推理（语义/逻辑/语法/二级辨析） · 定义判断（单定义/多定义核心要件提取） · 逻辑判断（翻译推理/集合推理/真假推理/排列组合/日常结论/加强论证/削弱论证/原因解释）。</li>\n  <li><strong>3. 言语理解</strong>：片段阅读（中心理解题/细节判断题/标题填入题/词句理解题） · 语句表达（语句排序题/语句填空题/接语选择题） · 逻辑填空（词义辨析/语境分析）。</li>\n  <li><strong>4. 数量关系</strong>：五大方法（代入排除/数字倍数特性/方程与不定方程/线段十字交叉/赋值法） · 八大高频题型（工程问题/行程问题/经济利润与分段计费/几何问题/容斥原理/排列组合与概率/周期年龄问题/和定最值与最不利构造）。</li>\n  <li><strong>5. 常识与政治理论</strong>：党的创新理论与重要会议文件 · 常见经济名词与宏观调控（财政/货币政策） · 法律（宪法/行政法/民法典/刑法/公务员法） · 党史与文史常识 · 科技航天、物理化学生物与地理国情。</li>\n</ul>\n"}, {"id": "d2g_shenlun", "cat": "D2G 备考核心清单", "title": "2. 申论知识模块清单与“按点给分”70+破局心法", "source": "miss-mumu/developer2gwy/doc/申论知识模块清单.md & Issue #36", "url": "https://github.com/miss-mumu/developer2gwy/blob/main/doc/%E7%94%B3%E8%AE%BA%E7%9F%A5%E8%AF%86%E6%A8%A1%E5%9D%97%E6%B8%85%E5%8D%97.md", "content": "\n<h3>一、为什么理工科和零基础考生完全不用怕申论？（摘自 D2G Issue #36）</h3>\n<p>很多考生误以为申论考的是文笔、辞藻和名言警句背诵，一提笔就发怵。但 D2G 团队实测证明：<strong>文科生和理科生的申论成绩与专业毫无因果关系！</strong></p>\n<ul>\n  <li><strong>申论考察的四项核心能力</strong>：① 阅读理解能力（全面把握给定资料，揭示本质）；② 综合分析能力（多角度思考，合理推断或评价）；③ 提出和解决问题能力（发现界定问题，提出可落地措施）；④ 文字表达能力（准确规范、简明畅达）。</li>\n  <li><strong>阅卷给分真相</strong>：除大作文外，<strong>前三道小题（单一题、综合题、公文题）全部实行“按采分词给分”——写中关键词即得分，写错写偏不倒扣分！</strong>材料里 70% 以上的原词都可以直接摘抄或提炼使用。</li>\n  <li><strong>核心训练目标</strong>：养成<strong>“见词、读句、识意”</strong>的条件反射——看到材料里一个具体案例或群众抱怨，立刻在脑中将它翻译为规范的“问题词 + 原因词 + 对策词”，并用<strong>“前置总括词 + 具体展开”</strong>写在答题卡格子上。</li>\n</ul>\n\n<h3>二、申论五大模块全清单（摘自《申论知识模块清单.md》&amp; kuriv 导图）</h3>\n<ol>\n  <li><strong>申论基础</strong>：大纲要求（材料为王、客观准确） · 要素题型识别 · 审题五要素（作答任务、作答身份、材料范围、特殊要求、字数要求） · 材料加工三法（同义合并、同范围合并、同主体合并）。</li>\n  <li><strong>单一题（归纳概括与提出对策）</strong>：概括问题（不科学/不健全/缺失/薄弱） · 概括影响（正面意义 vs 负面危害） · 概括原因（内因外因/思想制度监管技术） · 提出对策（直接摘抄 + 问题反推 + 经验借鉴，务必做到主体明确、手段具体、有针对性）。</li>\n  <li><strong>综合题</strong>：词句解释题（<strong>表层字面含义 + 深层问题/原因/意义关联要素 + 针对性对策</strong>） · 观点现象评析题（<strong>首句亮明态度：赞同/反对/辩证看待 + 多维理由分析 + 总结对策</strong>） · 对比分析题。</li>\n  <li><strong>公文题（贯彻执行）</strong>：格式三要素（标题 <code>关于+事由+的+文种</code>、顶格称谓、右下角发文单位与日期落款） · 方案类（指导意见/活动方案） · 总结类（工作汇报/讲话稿/调研报告/编者按） · 宣传类（公开信/倡议书/宣传稿，重呼吁号召） · 评论类（时评/短评，重观点与评析）。</li>\n  <li><strong>文章写作（大作文）</strong>：剖析题干与材料立意（总论点 + 3个分论点） · 标题锻造（对称式/主副式/比喻式） · 开头三法（总结式/阐释式/转折引入式） · 论证充实（申论材料案例概括引用 + 政策理论引证 + 正反对比） · 结尾升华（总结分论点 + 展望呼吁）。</li>\n</ol>\n"}, {"id": "d2g_method", "cat": "D2G 高效备考心法", "title": "3. 怎么高效准备公考：在职/基层服务平衡术与复盘反思法", "source": "miss-mumu/developer2gwy/doc/nav/怎么高效准备.md & Issue #9/#33/#34", "url": "https://github.com/miss-mumu/developer2gwy/blob/main/doc/nav/%E6%80%8E%E4%B9%88%E9%AB%98%E6%95%88%E5%87%86%E5%A4%87.md", "content": "\n<h3>一、“慢就是快”：扎好马步，拒绝假装努力（摘自《怎么高效准备.md》）</h3>\n<p>公考是一个从 0 到 1 的系统工程。备考中最常见的坑，是把大量时间花在<strong>到处搜集囤积网盘资料、纠结岗位、三天打鱼两天晒网</strong>上。D2G 团队给出的核心原则是：<strong>“慢慢学，踏实做，不停刷，扎好马步，打好基础”</strong>——百鸟在林不如一鸟在手，认准一套主流课程和题库，一个模块一个模块啃透。</p>\n\n<h3>二、基层服务/在职人员如何平衡日常工作与每日 2–3 小时备考？（摘自 Issue #9 &amp; #34）</h3>\n<ul>\n  <li><strong>1. 心态上接受“穿插切换”的常态</strong>：基层服务偶有下乡走访、迎检值班，不要因为某天计划被打乱就陷入焦虑自责。把备考当成持久战，<strong>注重单次学习的质量，学一个考点就彻底吃透一个考点</strong>，避免半生不熟导致反复重头再学。</li>\n  <li><strong>2. 碎片化学习的黄金铁律</strong>：<strong>“碎片化学习的本质，不是把系统课拆得七零八落，而是通过碎片时间处理次要任务，从而为晚间挤出整块系统学习与刷题的时间！”</strong>\n    <br/>· <strong>通勤/等候/午休碎片时间</strong>：用手机快扫图推特征、复盘错题本、默写资料分析公式、浏览时政热点；\n    <br/>· <strong>晚间整块 2—2.5 小时</strong>：开启免打扰模式，必须沉入纸质讲义和真题卷中，完整听完一节方法课 + 限时刷完配套题组。</li>\n  <li><strong>3. 目标拆解为可执行的具体动作</strong>：不要只喊“我要考上岸”的空口号，而是落实为<strong>“今天掌握截位直除并刷完 20 道资料分析”“今晚用前置总括词写完 1 道申论归纳概括题”“本周将资料分析正确率稳定在 85% 以上”</strong>。</li>\n</ul>\n\n<h3>三、如何通过总结与反思捅破提分窗户纸？（摘自 Issue #33）</h3>\n<ul>\n  <li><strong>用好错题笔记本（记 6 样核心）</strong>：① 重要公式与定理；② <strong>题型判定要素（看到什么题干信号用什么方法）</strong>；③ 易错细节陷阱；④ <strong>每学完一个模块亲手画一张思维导图</strong>；⑤ 典型错题的卡壳原因；⑥ 模考复盘感悟。</li>\n  <li><strong>“以教促学”输出检验法</strong>：学完一个专题后，合上书本，假装自己给别人讲课，把该题型的识别特征、解题步骤和避坑点口述出来。能流利讲清楚，才算真正变成考场上的肌肉记忆。</li>\n</ul>\n"}, {"id": "d2g_post_select", "cat": "D2G 选岗与体制认知", "title": "4. 招考岗位表 22 项深度解读、选岗博弈与编制全解析", "source": "miss-mumu/developer2gwy/doc/招考岗位解读.md & 编制概述.md & Issue #15/#17", "url": "https://github.com/miss-mumu/developer2gwy/blob/main/doc/%E6%8B%9B%E8%80%83%E5%B2%97%E4%BD%8D%E8%A7%A3%E8%AF%BB.md", "content": "\n<h3>一、选岗的第一性原理：用限制条件筛掉潜在竞争对手（摘自《招考岗位解读.md》&amp; Issue #17）</h3>\n<p>选择一个合适的岗位，上岸之路会顺畅一半。D2G 团队总结的选岗核心铁律只有一句话：<strong>“尽量选择自己全部满足限制条件的岗位，每多一条硬性限制，就帮你合法筛掉一大批竞争对手！”</strong></p>\n<ul>\n  <li><strong>招录对象（西部计划核心优势！）</strong>：重点锁定限制<strong>“服务基层项目人员（四项目人员）”</strong>或<strong>“应届高校毕业生”</strong>的岗位，坚决避开所有人都能报的“三不限”修罗场。</li>\n  <li><strong>专业要求</strong>：优先选具体专业名称（如“计算机科学与技术”），其次选专业小类（如“计算机类”），范围越窄竞争越小；注意必须使用最高学历对应的专业报考。</li>\n  <li><strong>政治面貌与附加条件</strong>：中共党员（含预备党员）、性别限制、户籍或生源地限制、法律职业资格证、基层工作年限等，只要你符合，一定要用足条件优势。</li>\n  <li><strong>职位简介与备注</strong>：注意查看备注栏是否有“最低服务年限 5 年（含试用期）”“需常年出差或夜间值守”及面试考察比例（1:3 还是 1:5）。</li>\n</ul>\n\n<h3>二、行政编、参公编、事业编与基层项目的真实区别（摘自《编制概述.md》）</h3>\n<table class=\"mini-ref-table\">\n  <thead>\n    <tr><th>编制/身份类型</th><th>管理依据与经费来源</th><th>核心特点与发展通道</th></tr>\n  </thead>\n  <tbody>\n    <tr><td><strong>行政编制（公务员）</strong></td><td>《公务员法》管理，行政财政全额统筹</td><td>国考、省考、选调生主力编制，享受公务员职级晋升（科员→四级至一级主任科员→处级）与车补。</td></tr>\n    <tr><td><strong>参公事业编制</strong></td><td>属事业编序列，但参照《公务员法》管理，财政全额统筹</td><td>实际待遇、职级晋升与行政编几乎无差别，可在参公单位与党政机关之间无障碍交流调动。</td></tr>\n    <tr><td><strong>事业编制</strong></td><td>《事业单位人事管理条例》，分公益一类（全额拨款）、公益二类（差额拨款）</td><td>以“中心、院、所、站、校、馆”结尾为主，走管理岗（十级至一级职员）或专业技术职称序列。</td></tr>\n    <tr><td><strong>西部计划 / 三支一扶</strong></td><td>高校毕业生基层服务项目（非正式在编，属于国家政策性基层服务经历）</td><td><strong>黄金跳板</strong>：服务期满且考核合格后，享国考/省考“四项目定向岗”报考资格、事业单位笔试加分、2年内视同应届生及工龄连续计算！</td></tr>\n  </tbody>\n</table>\n\n<h3>三、省直、市直、县乡公务员怎么选？（摘自 Issue #15 &amp; #34）</h3>\n<ul>\n  <li><strong>仕途天花板与薪资待遇</strong>：省直公务员 / 经济强市市直 &gt; 一般市州公务员 &gt; 省厅事业编 &gt; 乡镇公务员 &gt; 县乡事业编。</li>\n  <li><strong>上岸难度（从易到难）</strong>：县乡事业编 &lt; 乡镇公务员 / 西部地区基层岗 &lt; 市州直属机关 &lt; 省直与中央部委。</li>\n  <li><strong>务实建议</strong>：不要在笔试前过度纠结“去乡镇还是去市直”而荒废刷题——<strong>先用高分把主动权握在手里</strong>；国考、本省省考、邻省联考、选调生与事业单位联考每年有多轮机会，梯队报考稳扎稳打。</li>\n</ul>\n"}, {"id": "zxl_vocab", "cat": "高频讲义与知识速查", "title": "5. 言语理解高频易混实词 25 组与常考成语 40 组辨析全集", "source": "zhangxiangliang/civil-service-exam/posts/言语理解与表达/词汇积累.md & 词义辨析.md", "url": "https://github.com/zhangxiangliang/civil-service-exam/blob/master/posts/%E8%A8%80%E8%AF%AD%E7%90%86%E8%A7%A3%E4%B8%8E%E8%A1%A8%E8%BE%BE/%E8%AF%8D%E6%B1%87%E7%A7%AF%E7%B4%AF.md", "content": "\n<h3>一、高频易混实词精准辨析（摘自 zhangxiangliang《词汇积累.md》）</h3>\n<table class=\"mini-ref-table\">\n  <thead>\n    <tr><th>易混词组</th><th>核心侧重点与搭配差异（考场秒判标准）</th></tr>\n  </thead>\n  <tbody>\n    <tr><td><strong>漫延 vs 蔓延</strong></td><td><strong>漫延</strong>：专用于水向四处铺满流淌；<strong>蔓延</strong>：用于植物生长、火势扩张或抽象事物（疫情/风气）扩散。</td></tr>\n    <tr><td><strong>力行 vs 厉行</strong></td><td><strong>力行</strong>：侧重亲自实践（身体力行）；<strong>厉行</strong>：侧重严格执行制度措施（厉行节约、厉行法治）。</td></tr>\n    <tr><td><strong>截止 vs 截至</strong></td><td><strong>截止</strong>：表时间已停止，后面不能直接跟时间宾语（只能说“截止到5月”）；<strong>截至</strong>：表“直到…”，后直接跟时间（“截至5月”）。</td></tr>\n    <tr><td><strong>品行 vs 品性</strong></td><td><strong>品行</strong>：行为作风，搭配“品行端正”；<strong>品性</strong>：性格品质，搭配“品性温和/纯良”。</td></tr>\n    <tr><td><strong>权利 vs 权力</strong></td><td><strong>权利</strong>：公民或法人依法享有的权益（人民有权利）；<strong>权力</strong>：政治上的强制力量或职责范围内的支配力（国家机关有权力）。</td></tr>\n    <tr><td><strong>推脱 vs 推托</strong></td><td><strong>推脱</strong>：推卸逃避自己的责任（推脱责任）；<strong>推托</strong>：借故拒绝别人的请求（推托有事不去）。</td></tr>\n    <tr><td><strong>约束 vs 制约</strong></td><td><strong>约束</strong>：多指自我规范或内部条文限制；<strong>制约</strong>：甲事物的存在变化决定或限制乙事物（相互制约）。</td></tr>\n    <tr><td><strong>延续 vs 延绵</strong></td><td><strong>延续</strong>：照原样继续下去不中断；<strong>延绵</strong>：绵延不断、保持连贯（可包含演变与创新）。</td></tr>\n    <tr><td><strong>次第 vs 依次</strong></td><td><strong>次第</strong>：书面文艺语体，强调按特定顺序一个接一个（“山顶千门次第开”）；<strong>依次/相继</strong>：中性平实陈述。</td></tr>\n    <tr><td><strong>多维/多极/多边/多元</strong></td><td>固定搭配：<strong>多维</strong>空间/视角 · <strong>多极</strong>世界格局 · <strong>多边</strong>外交/国家合作 · <strong>多元</strong>文化/主体。</td></tr>\n    <tr><td><strong>爱戴 vs 爱护</strong></td><td><strong>爱戴</strong>：下级对上级、晚辈对长辈敬爱拥护；<strong>爱护</strong>：上级对下级、对晚辈或对公物草木的珍惜保护。</td></tr>\n    <tr><td><strong>决定/表明/揭示 vs 暴露</strong></td><td>前三者为<strong>中性词</strong>；<strong>暴露</strong>多含贬义（暴露出短板、漏洞或野心）。</td></tr>\n  </tbody>\n</table>\n\n<h3>二、行测最爱设坑的 24 组高频成语辨析（摘自《词汇积累.md》）</h3>\n<ul>\n  <li><strong>1. 首当其冲 vs 首屈一指</strong>：<strong>首当其冲</strong>指最先受到攻击或遭遇灾祸（高频误用为“排第一”）；<strong>首屈一指</strong>才表示位居第一位。</li>\n  <li><strong>2. 望尘莫及 vs 鞭长莫及</strong>：<strong>望尘莫及</strong>指远远落后赶不上；<strong>鞭长莫及</strong>指距离太远力量达不到（不表落后）。</li>\n  <li><strong>3. 相提并论 vs 同日而语</strong>：<strong>相提并论</strong>把不同的人或事物放在一起谈论；<strong>同日而语</strong>把同一事物在不同时期的状况对比（常用于否定句“不可同日而语”）。</li>\n  <li><strong>4. 南辕北辙 vs 针锋相对</strong>：<strong>南辕北辙</strong>指行动和目的相反；<strong>针锋相对</strong>指双方观点、策略尖锐对立。</li>\n  <li><strong>5. 名声鹊起 vs 门庭若市</strong>：<strong>名声鹊起</strong>形容知名度迅速提高；<strong>门庭若市</strong>形容来往客人极多、十分热闹（不直接等于出名）。</li>\n  <li><strong>6. 积重难返 vs 根深蒂固</strong>：<strong>积重难返</strong>指长期形成的不良习俗弊端难改；<strong>根深蒂固</strong>指思想观念基础深厚不易动摇。</li>\n  <li><strong>7. 凤毛麟角 vs 硕果仅存</strong>：<strong>凤毛麟角</strong>形容极其稀少珍贵；<strong>硕果仅存</strong>强调唯一留存下来的。</li>\n  <li><strong>8. 萧规曹随 vs 推陈出新</strong>：<strong>萧规曹随</strong>指完全沿袭前人规章制度；<strong>推陈出新</strong>指在继承基础上去掉旧糟粕、创造新精华。</li>\n  <li><strong>9. 越俎代庖 vs 李代桃僵</strong>：<strong>越俎代庖</strong>指超出自己职权范围包办他人事务；<strong>李代桃僵</strong>指代人受过或互相顶替。</li>\n  <li><strong>10. 本末倒置 vs 喧宾夺主 vs 反客为主</strong>：<strong>本末倒置</strong>把主次轻重颠倒；<strong>喧宾夺主</strong>指外来的次要事物占据了原有的主要地位；<strong>反客为主</strong>指由被动转为主动。</li>\n  <li><strong>11. 不胜枚举 vs 罄竹难书</strong>：<strong>不胜枚举</strong>为中性词，仅表数量极多；<strong>罄竹难书</strong>为强贬义，专指罪恶极多写不完。</li>\n  <li><strong>12. 信口开河 vs 信口雌黄</strong>：<strong>信口开河</strong>指随口乱说；<strong>信口雌黄</strong>语义更重，指不顾事实随口污蔑诽谤。</li>\n</ul>\n"}, {"id": "zxl_changshi", "cat": "高频讲义与知识速查", "title": "6. 政治哲学、中国地理国情、历史朝代与高新科技必背讲义", "source": "zhangxiangliang/civil-service-exam/posts/公共基础知识/*.md", "url": "https://github.com/zhangxiangliang/civil-service-exam/tree/master/posts/%E5%85%AC%E5%85%B1%E5%9F%BA%E7%A1%80%E7%9F%A5%E8%AF%86", "content": "\n<h3>一、马克思主义哲学核心体系（摘自《政治哲学.md》&amp; MindNode）</h3>\n<ul>\n  <li><strong>哲学基本派别</strong>：① <strong>古代朴素唯物主义</strong>（把世界本源归结为水、火、气、土等具体物质形态，如“天地合而万物生”“天行有常”）；② <strong>近代形而上学唯物主义</strong>（认为原子是本源，具有机械性、孤立静止片面性，如“人是机器”）；③ <strong>主观唯心主义</strong>（把人的意志、心灵、感觉当本源，如“万物皆备于我”“心外无物”“存在就是被感知”）；④ <strong>客观唯心主义</strong>（把“理”“理念”“绝对精神”“道”当本源，如“理在事先”“道生一”）。</li>\n  <li><strong>唯物辩证法三大规律</strong>：① <strong>对立统一规律（核心和实质）</strong>：内因是变化的根据，外因是变化的条件；矛盾普遍性与特殊性辩证统一（共性与个性）；主次矛盾（办事情抓重点：“牵牛要牵牛鼻子”“擒贼先擒王”）与矛盾主次方面（看问题分清主流与支流）。② <strong>质量互变规律</strong>：量变是质变的必要准备，质变是量变的必然结果，坚持适度原则。③ <strong>否定之否定规律</strong>：辩证否定的实质是“扬弃”（既克服又保留），事物发展是前进性与曲折性的统一（螺旋式上升、波浪式前进）。</li>\n</ul>\n\n<h3>二、中国地理国情速记（摘自《国情概况.md》&amp;《地理自然.md》）</h3>\n<ul>\n  <li><strong>领土四端</strong>：最北（漠河以北黑龙江主航道中心线）、最南（南沙群岛曾母暗沙）、最西（新疆帕米尔高原）、最东（黑龙江与乌苏里江主航道中心线汇合处）。</li>\n  <li><strong>14个陆上邻国顺口溜</strong>：<code>朝俄蒙哈吉塔阿，巴印尼泊和不丹，缅甸老挝接越南，陆上邻国依次连</code>。</li>\n  <li><strong>三级阶梯分界山脉</strong>：一二级阶梯分界线为<strong>昆仑山—祁连山—横断山脉</strong>；二三级阶梯分界线为<strong>大兴安岭—太行山—巫山—雪峰山</strong>。</li>\n  <li><strong>地形与河湖之最</strong>：四大高原（青藏最大、内蒙古最平坦、黄土水土流失、云贵喀斯特地貌）；四大盆地（塔里木最大、柴达木海拔最高“聚宝盆”、准噶尔、四川“天府之国”）；五大淡水湖（鄱阳湖最大、洞庭湖、太湖、洪泽湖、巢湖），最大咸水湖为青海湖。</li>\n  <li><strong>太阳大气层（由里向外）</strong>：光球层（黑子） → 色球层（耀斑，扰动电离层影响无线电短波通信） → 日冕层（太阳风/磁暴/极光）。</li>\n</ul>\n\n<h3>三、中国历史与文学文化（摘自《人文历史.md》）</h3>\n<ul>\n  <li><strong>历史朝代歌</strong>：<code>夏商与西周，东周分两段，春秋和战国，一统秦两汉，三分魏蜀吴，二晋前后延，南北朝并立，隋唐五代传，宋元明清后，皇朝至此完</code>。</li>\n  <li><strong>文学史第一</strong>：《诗经》（第一部诗歌总集，风雅颂/赋比兴）、《楚辞》（第一部浪漫主义诗歌总集）、《史记》（第一部纪传体通史）、《水浒传》（第一部白话章回小说）、《三国演义》（第一部长篇历史章回小说）、《狂人日记》（现代第一篇白话短篇小说）。</li>\n  <li><strong>唐宋名家称号</strong>：诗仙李白、诗圣杜甫（三吏三别）、诗佛王维、诗鬼李贺、诗魔/诗王白居易、诗狂贺知章；元曲四大家（关汉卿、马致远、郑光祖、白朴）。</li>\n</ul>\n\n<h3>四、高新科技与新能源常识（摘自《高新科技.md》）</h3>\n<ul>\n  <li><strong>量子通信</strong>：利用量子纠缠效应与不可克隆原理传递信息，我国发射世界首颗量子科学实验卫星“墨子号”，建成首条量子保密通信干线“京沪干线”。</li>\n  <li><strong>能源分类</strong>：一次能源（煤炭、石油、天然气、核能、太阳能、风能、水能、地热能、潮汐能、生物质能） vs 二次能源（电力、汽油、柴油、煤气、焦炭、沼气）。</li>\n</ul>\n"}, {"id": "d2g_reality", "cat": "D2G 选岗与体制认知", "title": "7. 公考真实难度拆解、思想建设与备考心态防崩指南", "source": "miss-mumu/developer2gwy/doc/公考概述、思想建设以及物质准备.md & question/*.md", "url": "https://github.com/miss-mumu/developer2gwy/blob/main/doc/%E5%85%AC%E8%80%83%E6%A6%82%E8%BF%B0%E3%80%81%E6%80%9D%E6%83%B3%E5%BB%BA%E8%AE%BE%E4%BB%A5%E5%8F%8A%E7%89%A9%E8%B4%A8%E5%87%86%E5%A4%87.md", "content": "\n<h3>一、公考的真实难度到底怎么样？（摘自 D2G《公考真实的难度到底怎么样？.md》）</h3>\n<p>可以肯定地告诉大家，公考各环节拆解开来，绝对不是高不可攀的天赋竞赛：</p>\n<ul>\n  <li><strong>行测</strong>：中学文科（常识） + 中学语文（言语理解） + 小学奥数（数量关系） + 高中理科（逻辑推理） + 初中数学统计（资料分析）。</li>\n  <li><strong>申论</strong>：高中语文阅读归纳（单一题、综合题、公文题） + 政论文框架写作（申论大作文）。</li>\n  <li><strong>面试</strong>：结构化综合素质考察——考官更在乎沟通交流、应变能力、逻辑条理、仪表谈吐与务实态度，而不是让你背诵高深专业学术名词或指点江山。</li>\n  <li><strong>体检 / 政审 / 考察</strong>：无器质性重大疾病、三代直系亲属无重大刑事犯罪、个人征信与品行端正即可顺利通过。</li>\n  <li><strong>核心结论</strong>：“上岸并不是精英游戏，更不是天赋大比拼。<strong>公考对于绝大多数普通人的唯一门槛，在于能否心无旁骛地坚持走完这 100 天。只要你的准备和付出高于同岗对手一点点，就能稳稳上岸！</strong>”</li>\n</ul>\n\n<h3>二、为什么有人考了几年还没上岸？如何防止心态崩溃？（摘自《心态快崩了.md》）</h3>\n<ul>\n  <li><strong>最大病因是“战线拖太长卻精力不专一”</strong>：间歇性踌躇满志、三天打鱼两天晒网，效果一定起伏不定。相反，<strong>集中 3 个月（100 天）每天雷打不动投入 2–3 小时高质量备考，足以从零基础把行测和申论打磨到进面线以上；再用 1 个月脱敏训练开口答题，足以在面试考场上对答如流</strong>。</li>\n  <li><strong>学习环境建设</strong>：下班或服务结束后，尽量在单位阅览室、安静书桌或图书馆完成当日 2.5 小时任务，手机开启专注免打扰，学完立即打勾打卡，用每天肉眼可见的进度条对抗焦虑。</li>\n</ul>\n"}, {"id": "d2g_life", "cat": "D2G 选岗与体制认知", "title": "8. 体制内工作内容、人际关系法则与“做人做事”核心竞争力", "source": "miss-mumu/developer2gwy/doc/nav/人际关系.md & 核心竞争力.md", "url": "https://github.com/miss-mumu/developer2gwy/blob/main/doc/nav/%E4%BA%BA%E9%99%85%E5%85%B3%E7%B3%BB.md", "content": "\n<h3>一、体制内与企业环境的本质差异对照（摘自 D2G《人际关系.md》）</h3>\n<p>了解体制内的真实运行逻辑，不仅有助于入职后快速适应，更能帮你在<strong>结构化面试的人际关系题、应急应变题</strong>中答出考官最认可的“政府思维”：</p>\n<table class=\"mini-ref-table\">\n  <thead>\n    <tr><th>对比维度</th><th>企业职场逻辑</th><th>体制内机关事业单位逻辑</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>核心导向</td><td>商业利润与KPI结果导向</td><td>依法依规、群众满意、大局稳定与程序规范</td></tr>\n    <tr><td>同事交往周期</td><td>流动性大，平均2—3年跳槽</td><td>共事十几年甚至几十年，讲究互帮互助、互相搭台</td></tr>\n    <tr><td>沟通禁忌</td><td>崇尚个人英雄主义或互联网黑话</td><td><strong>忌越权表态、忌推诿扯皮、忌生造黑话，重请示汇报与团结协作</strong></td></tr>\n  </tbody>\n</table>\n\n<h3>二、体制内安身立命的核心法则：真诚、踏实、边界感（摘自《核心竞争力.md》）</h3>\n<ul>\n  <li><strong>1. 对自己真诚</strong>：客观认识自身优缺点，懂规矩、守底线，不该说的话不说，不该碰的红线不碰。</li>\n  <li><strong>2. 对他人真诚</strong>：说话办事不卑不亢、有一说一；同事之间“互相搭台不拆台”，遇到协办工作主动补位沟通。</li>\n  <li><strong>3. 把互联网黑话转化为接地气的机关实务语言</strong>：切忌在公文和面试中堆砌“多端分发、跨端赋能、闭环抓手”等空洞词汇，而要用<strong>“把文件学透吃透、下发各科室传阅、逐项督促落实到位、定期开展回头看”</strong>这样实在、规范的机关表达。</li>\n</ul>\n"}];

window.INTERVIEW_ZONE = {"types": "\n<div class=\"int-section-intro\">\n  <strong>📌 导读：</strong>以下结构化面试核心题型框架完整提取自开源仓库 <code>kuriv/civil-service-exam/面试/面试.emmx</code> 思维导图，涵盖国考与省考面试 <strong>95% 以上必考母题</strong>。建议在笔试中后期及进面后，结合下方“金句语料库”每天开口晨读 15 分钟。\n</div>\n\n<div class=\"int-cards-grid\">\n  <div class=\"int-card\">\n    <div class=\"int-card-head\">\n      <span class=\"int-num\">题型 01</span>\n      <h3>社会现象类（综合分析必考第1题）</h3>\n    </div>\n    <div class=\"int-flow-steps\">\n      <span class=\"step-chip\">① 破题表态</span> → <span class=\"step-chip\">② 多维分析（影响+原因）</span> → <span class=\"step-chip\">③ 落地对策</span> → <span class=\"step-chip\">④ 总结升华</span>\n    </div>\n    <ul>\n      <li><strong>精准表态三选一</strong>：\n        <br/>· <strong>正面现象/好政策</strong>：值得点赞支持，体现了以人民为中心的服务理念，具有示范推广价值；\n        <br/>· <strong>负面乱象/失职行为</strong>：令人痛心/亟待整治，暴露出部分单位作风不实与监管缺位，必须引起高度重视；\n        <br/>· <strong>争议现象/一刀切政策</strong>：应辩证客观看待——出发点虽好，但执行中简单机械，无异于扬汤止沸，唯有兼顾各方诉求方能实现标本兼治。</li>\n      <li><strong>原因剖析三层次（微观→中观→宏观）</strong>：个人层面（法律意识薄弱/逐利心态/能力欠缺不会为或庸政懒政不想为） → 监管执行层面（制度缺位/协同不畅/重留痕轻实效） → 社会与法规层面（配套法规滞后/考核指挥棒偏差/宣传引导不足）。</li>\n      <li><strong>高分对策万金油（思想+制度+监管+技术+共治）</strong>：加强宣传教育与业务培训 → 完善配套细则与考核机制 → 强化常态化监管与严肃问责 → 运用“互联网+大数据”赋能便民服务 → 畅通群众监督渠道实现社会共治。</li>\n    </ul>\n  </div>\n\n  <div class=\"int-card\">\n    <div class=\"int-card-head\">\n      <span class=\"int-num\">题型 02</span>\n      <h3>应急应变类（突发事件处置）</h3>\n    </div>\n    <div class=\"int-flow-steps\">\n      <span class=\"step-chip\">① 稳控现场/亮明身份</span> → <span class=\"step-chip\">② 轻重缓急分类处置</span> → <span class=\"step-chip\">③ 请示汇报与善后</span> → <span class=\"step-chip\">④ 复盘长效机制</span>\n    </div>\n    <ul>\n      <li><strong>角色定位铁律</strong>：牢记自身职责权限，<strong>不越权、不推诿；权限不明或重大事项第一时间请示领导</strong>，保持沉着冷静与阳光心态。</li>\n      <li><strong>矛盾排序四优先</strong>：生命安全第一 → 防止事态扩大（隔离安抚情绪激动群众、避免舆情发酵） → 保全核心工作（如确保重要会议/考试/窗口服务继续进行） → 逐一核实解决具体诉求。</li>\n      <li><strong>答题避坑原则</strong>：做<strong>合理阳光假设，绝不给自己挖坑</strong>；重点放在“当下用什么具体动作解决矛盾”，最后补一句“事后复盘查漏补缺，健全应急预案”。</li>\n    </ul>\n  </div>\n\n  <div class=\"int-card\">\n    <div class=\"int-card-head\">\n      <span class=\"int-num\">题型 03</span>\n      <h3>人际关系类（机关四大主体相处之道）</h3>\n    </div>\n    <div class=\"int-flow-steps\">\n      <span class=\"step-chip\">① 阳光心态/自省不抱怨</span> → <span class=\"step-chip\">② 工作为重/主动破冰</span> → <span class=\"step-chip\">③ 分主体妥善化解</span> → <span class=\"step-chip\">④ 长效磨合提升</span>\n    </div>\n    <ul>\n      <li><strong>对待领导</strong>：<strong>尊重服从、协助支持、请示汇报、委婉建议</strong>（领导批评虚心接受并立行立改；不同领导交办冲突时，先看轻重缓急并主动向领导汇报协调，绝不让领导之间产生误会）。</li>\n      <li><strong>对待同事/老同志</strong>：<strong>互帮互助、加强沟通、工作为先、求同存异</strong>（向老同志虚心请教业务经验，对配合不畅的同事换位思考、私下坦诚交流，主动分担急难任务）。</li>\n      <li><strong>对待基层群众</strong>：<strong>动之以情、晓之以理、言之以法、给建议给举措</strong>（先递一杯热水倾听诉求，用大白话讲透政策红线，在合规范围内帮群众跑腿解决实际困难）。</li>\n      <li><strong>对待下属/志愿者</strong>：<strong>关心引导、帮助提升、严管厚爱、压实责任</strong>。</li>\n    </ul>\n  </div>\n\n  <div class=\"int-card\">\n    <div class=\"int-card-head\">\n      <span class=\"int-num\">题型 04</span>\n      <h3>调研调查类（组织管理高频母题）</h3>\n    </div>\n    <div class=\"int-flow-steps\">\n      <span class=\"step-chip\">① 摸底准备</span> → <span class=\"step-chip\">② 多渠道精准调研</span> → <span class=\"step-chip\">③ 交叉对比汇总报告</span>\n    </div>\n    <ul>\n      <li><strong>调研准备</strong>：查阅过往工作台账与先进地区案例；准备问卷、录音笔等物资；抽调熟悉业务、懂当地方言、沟通亲和力强的工作人员及专家组成调研组。</li>\n      <li><strong>对象与方式全覆盖</strong>：（如调研老旧小区改造/脏乱差）覆盖<strong>居民业主、物业人员、周边商户、社区网格员与街道干部</strong>；采取<strong>线上政务公众号问卷 + 线下广场设点/入户走访 + 召开代表座谈会 + 实地暗访体验</strong>相结合，摸清真实现状、痛点诉求与专家建议。</li>\n      <li><strong>报告产出</strong>：剔除无效数据，进行<strong>纵向历史同比与横向地区对比</strong>，用可视化图表与典型案例形成既有问题清单又有可行建议的调研报告，呈报领导决策。</li>\n    </ul>\n  </div>\n\n  <div class=\"int-card\">\n    <div class=\"int-card-head\">\n      <span class=\"int-num\">题型 05</span>\n      <h3>宣传教育与学习培训类</h3>\n    </div>\n    <div class=\"int-flow-steps\">\n      <span class=\"step-chip\">① 请示定调与受众摸底</span> → <span class=\"step-chip\">② 分众化内容与创新形式</span> → <span class=\"step-chip\">③ 考核验收与长效转化</span>\n    </div>\n    <ul>\n      <li><strong>宣传教育亮点动作</strong>：紧扣政策核心与群众关切定制内容；<strong>“线上+线下”立体覆盖</strong>——线上利用微视频、一图读懂、故事漫画、微信公众号推送；线下深入社区广场、村委会大喇叭、宣讲会、发放便民明白卡；事后通过问卷回访评估知晓率。</li>\n      <li><strong>学习培训闭环设计</strong>：按需施教（业务技能+政策理论+群众沟通实操） → 邀请业务骨干、专家学者授课 → 采用<strong>“集中授课 + 典型案例研讨 + 实地观摩 + 情景模拟演练”</strong>避免枯燥念稿 → 严格考勤与结业测试，将培训表现纳入个人考核。</li>\n    </ul>\n  </div>\n\n  <div class=\"int-card\">\n    <div class=\"int-card-head\">\n      <span class=\"int-num\">题型 06</span>\n      <h3>会议组织、活动策划与专项整治类</h3>\n    </div>\n    <div class=\"int-flow-steps\">\n      <span class=\"step-chip\">① 会前/赛前周密筹备</span> → <span class=\"step-chip\">② 会中/执法规范有序</span> → <span class=\"step-chip\">③ 会后督办与常态回头看</span>\n    </div>\n    <ul>\n      <li><strong>会议组织三阶段</strong>：<strong>会前</strong>（请示领导定议题时间、成立会务组、准备材料PPT与会场后勤、精准通知参会人并确认回执） → <strong>会中</strong>（签到引导、议程把控、专人录音与会议纪要） → <strong>会后</strong>（整理印发会议纪要、文件归档、<strong>对议定事项建立台账跟踪督办</strong>）。</li>\n      <li><strong>专项整治四步法（kuriv 经典框架）</strong>：① <strong>摸底宣传</strong>（下发整改告知书，讲明标准与期限，引导自查自纠）；② <strong>分类帮扶</strong>（对存在实际困难的群众/商户提供合规指引与资源疏导，不搞简单一刀切）；③ <strong>联合执法</strong>（随机抽查与突击检查结合，依法依规处罚整改）；④ <strong>长效监督</strong>（定期不定期“回头看”，畅通群众举报渠道防止反弹）。</li>\n    </ul>\n  </div>\n</div>\n", "flow": "\n<div class=\"int-section-intro\">\n  <strong>📌 导读：</strong>本节完整摘录自开源仓库 <code>miss-mumu/developer2gwy</code>（《上岸整套流程概述.md》及《面试问题手册》），为你还原最真实的公务员面试考场细节与 13 步通关全流程。\n</div>\n\n<div class=\"int-cards-grid\">\n  <div class=\"int-card\">\n    <div class=\"int-card-head\">\n      <span class=\"int-num\">考场揭秘 01</span>\n      <h3>面试考场真实配置与当场出分机制</h3>\n    </div>\n    <ul>\n      <li><strong>标准考场阵容（11人左右）</strong>：正前方一排通常坐着 <strong>7 名考官</strong>（1名主考官居中 + 6名考官），两侧配有 <strong>2 名计分核分工作人员、2 名纪检监督员</strong>，你坐在正对主考官的考生席。</li>\n      <li><strong>如何保证绝对公平（双盲抽签）</strong>：早上 7:00（下午 13:00）考生集中候考，收缴全部通讯设备；<strong>考官抽考场号，考生抽出场顺序号</strong>，考场上禁止透露本人姓名、籍贯、毕业院校及父母信息（统称“各位考官，我是 X 号考生”）。</li>\n      <li><strong>评分规则（去掉最高最低分）</strong>：一般 15 分钟回答 3 道题（或 20 分钟 4 道题），去掉一个最高分和一个最低分后取平均分，<strong>隔位候分、当场宣布并签字确认面试成绩单</strong>。</li>\n    </ul>\n  </div>\n\n  <div class=\"int-card\">\n    <div class=\"int-card-head\">\n      <span class=\"int-num\">考场揭秘 02</span>\n      <h3>考官最青睐什么样的考生？（考官视角 vs 考生视角）</h3>\n    </div>\n    <ul>\n      <li><strong>1. 眼神交流高于背诵词藻</strong>：考官连续听几十名考生答题极度疲劳。如果全程低头死盯草稿纸念稿，基本难拿高分；<strong>抬头与主考官及两侧考官自然眼神交流、语速沉稳、像日常汇报工作一样娓娓道来</strong>，印象分直接拉满。</li>\n      <li><strong>2. 逻辑外显（第一、第二、第三）</strong>：考官手里有评分参考要点，答题务必使用清晰的逻辑序数词（“首先/第一，在思想层面…；其次/第二，在制度落实上…”），让考官一耳朵抓到你的得分点。</li>\n      <li><strong>3. 着装与仪态得体</strong>：无需昂贵名牌，深色合身西装/带领衬衫或整洁商务便装即可，头发清爽、精神饱满；进门敲门致意、鞠躬问好、轻推椅子入座，展现青年干部的稳重朝气。</li>\n    </ul>\n  </div>\n\n  <div class=\"int-card\">\n    <div class=\"int-card-head\">\n      <span class=\"int-num\">考场揭秘 03</span>\n      <h3>考场紧张发抖、大脑一片空白怎么急救？</h3>\n    </div>\n    <ul>\n      <li><strong>审题 1 分钟草稿纸怎么写</strong>：千万别写完整句子！只写<strong>“3 个核心关键词 + 主体维度（如：群众/商户/街道；事前/事中/事后）”</strong>，留足精力组织口头语言。</li>\n      <li><strong>大脑空白 10 秒缓冲术</strong>：如果听到陌生题目瞬间懵了，先平稳复述题干核心背景（“各位考官，题目中提到的 XX 现象/突发情况，确实是我们基层工作中经常面临的难点…”），边说边在脑中调取“主体分析法”或“事前事中事后”框架，情绪会立刻稳定下来。</li>\n      <li><strong>D2G 脱敏训练法</strong>：面试不需要准备半年，<strong>集中 3—4 周每天对镜或录音开口练 3 道真题</strong>，听自己的录音纠正常见的“嗯、啊、那个”口头禅，四周足以从支支吾吾蜕变为对答如流。</li>\n    </ul>\n  </div>\n\n  <div class=\"int-card\">\n    <div class=\"int-card-head\">\n      <span class=\"int-num\">全流程全景</span>\n      <h3>公考从报名到入职 13 步完整时间轴（D2G 原文）</h3>\n    </div>\n    <ol>\n      <li><strong>1—3. 发布公告与报名选岗</strong>：招录机关上报计划 → 官网发布公告与职位表 → 网上提交报名、等待资格初审、缴费并打印准考证。</li>\n      <li><strong>4. 公共科目笔试</strong>：通常周日上午 9:00-11:00 行测，下午 14:00-17:00 申论。</li>\n      <li><strong>5—6. 笔试出分与资格复审</strong>：笔试后约 1 个月查分 → 进面考生携带身份证、毕业证学位证、<strong>《西部计划志愿服务证》及考核鉴定表</strong>原件参加现场或线上资格复审（不合格者由后一名递补）。</li>\n      <li><strong>7—8. 结构化面试与总成绩公布</strong>：复审后约 1—2 周参加面试，当场拿面试分 → 1 周内官网公布“笔试+面试”总成绩排名及进入体检名单。</li>\n      <li><strong>9—13. 体检、政审考察、公示与报到</strong>：统一集合赴指定医院体检 → 招录单位人事干部赴服务单位/学校调档政审与实地考察谈话 → 官网拟录用公示（5—7个工作日） → 接录用通知正式报到入编！</li>\n    </ol>\n  </div>\n</div>\n", "volunteer": "\n<div class=\"int-section-intro\">\n  <strong>🌟 西部计划志愿者专属优势：</strong>在面试考场上，考官最烦“满嘴培训班套话、完全不懂基层实际”的考生。而你作为<strong>大学生志愿服务西部计划志愿者</strong>，手握最鲜活的乡镇/街道/团委/社区一线实务经验！只要在自我认知、群众工作、应急组织题中自然融入基层细节（不刻意炫耀、不违规透露真实地名姓名），就能瞬间与其他应届生拉开 3—5 分差距！\n</div>\n\n<div class=\"int-cards-grid\">\n  <div class=\"int-card\">\n    <div class=\"int-card-head\">\n      <span class=\"int-num\">高分转化 01</span>\n      <h3>人际与群众沟通题：用“院坝会/入户走访”替代空洞套话</h3>\n    </div>\n    <p><strong>❌ 普通模板答题</strong>：“我会动之以情、晓之以理，耐心向群众解释政策，消除群众的误解……”</p>\n    <p><strong>✅ 西部计划高分示范</strong>：“在基层服务期间我深刻体会到，群众不理解政策，往往是因为书面条文太专业、或者担心自身切身利益受损。因此，第一步我不会生硬地拿文件去压，而是先坐下来拉家常，找村里有威望的老党员、网格员一起入户，拿纸笔给大爷大妈算清‘明白账’——比如补贴怎么发、线上医保怎么手把手代办；把‘文件话’翻译成老百姓听得懂的‘家常话’，心结自然就解开了。”</p>\n  </div>\n\n  <div class=\"int-card\">\n    <div class=\"int-card-head\">\n      <span class=\"int-num\">高分转化 02</span>\n      <h3>组织调研与宣传题：亮出“一户一档台账”与分众宣讲细节</h3>\n    </div>\n    <p><strong>❌ 普通模板答题</strong>：“我会通过线上发微信公众号、线下挂横幅发传单的方式开展防诈/医保宣传……”</p>\n    <p><strong>✅ 西部计划高分示范</strong>：“结合基层实际，年轻人白天大多外出务工，留守老人看不清长篇文字传单。因此宣传不能大水漫灌：第一，针对独居和留守老人，我们会结合日常走访台账，上门帮他们安装国家反诈中心APP并把预警电话贴在座机旁；第二，利用乡村大喇叭、赶集日便民服务摊位和傍晚‘院坝微宣讲’，用身边真实被骗案例现场说法；第三，在村组微信群推送 30 秒方言短视频，确保宣传真正入脑入心。”</p>\n  </div>\n\n  <div class=\"int-card\">\n    <div class=\"int-card-head\">\n      <span class=\"int-num\">高分转化 03</span>\n      <h3>应急处突与多任务统筹题：展现“基层兜底与闭环落实”</h3>\n    </div>\n    <p><strong>❌ 普通模板答题</strong>：“面对多项紧急任务，我会分清轻重缓急，加班加点保质保量完成……”</p>\n    <p><strong>✅ 西部计划高分示范</strong>：“基层工作千头万绪，常遇到迎检材料报送、突发防汛值守与群众窗口办事撞在一起的情况。我的处置原则是：<strong>安全底线与群众现场诉求第一、有时限的刚性报送第二、常规台账整理第三</strong>。首先立即安抚现场办事群众，开启延时服务或引导线上预约；其次向分管领导简要汇报手头任务冲突，协调同事交叉补位核对紧急报表数据；最后利用晚间复盘归档，把临时应急动作固化为标准化工作清单。”</p>\n  </div>\n\n  <div class=\"int-card\">\n    <div class=\"int-card-head\">\n      <span class=\"int-num\">高分转化 04</span>\n      <h3>岗位匹配与职业价值观题：诠释“听得懂方言、咽得下委屈、干得出实绩”</h3>\n    </div>\n    <p><strong>✅ 考场收尾金句储备（可直接背诵化用）</strong>：</p>\n    <ul>\n      <li>“脚下沾有多少泥土，心中就沉淀多少真情。在西部基层的志愿服务经历，让我完成了从‘象牙塔书生’到‘基层实干者’的蜕变，学会了在繁琐的具体事务中保持耐心，在直面群众急难愁盼时主动担当。”</li>\n      <li>“上面千条线，下面一根针。作为一名准基层公务员，我们就是连接党和政府与人民群众的‘最后一公里’。无论未来分在哪个科室，我都会坚持把小事办实、把急事办妥、把难事办好。”</li>\n    </ul>\n  </div>\n</div>\n", "checkup": "\n<div class=\"int-section-intro\">\n  <strong>📌 导读：</strong>以下内容完整复制自 <code>miss-mumu/developer2gwy</code> 仓库的《体检的最佳实践、注意事项.md》《政审的最佳实践、注意事项.md》与《考察的最佳实践、注意事项.md》，供进面后随时对照自查。\n</div>\n\n<div class=\"int-cards-grid\">\n  <div class=\"int-card\">\n    <div class=\"int-card-head\">\n      <span class=\"int-num\">体检指南</span>\n      <h3>《公务员录用体检通用标准（试行）》核心条款与考前避坑（D2G 原文）</h3>\n    </div>\n    <ul>\n      <li><strong>核心合格指标速查</strong>：\n        <br/>· <strong>血压（第2条）</strong>：收缩压 &lt; 140mmHg，舒张压 &lt; 90mmHg 合格（体检当天早起紧张若偏高，可静坐深呼吸后申请复测）；\n        <br/>· <strong>血液（第3条）</strong>：单纯性缺铁性贫血，血红蛋白男性高于 90g/L、女性高于 80g/L 合格；\n        <br/>· <strong>肝功与内科（第1/5/6/7/9/10条）</strong>：无器质性心脏病、无急慢性肝炎及肝硬化、无慢性肾炎、无糖尿病等严重内分泌疾病；\n        <br/>· <strong>视力与听力（第19/20条）</strong>：普通岗位双眼矫正视力（戴眼镜）不低于 4.8（小数视力 0.6）即合格（人民警察等特殊岗位按特殊标准执行）。</li>\n      <li><strong>⚠️ 体检前一周五大铁律</strong>：① 严禁熬夜、严禁饮酒、忌高油高糖高蛋白宵夜（防止转氨酶和尿酸一过性升高！）；② 严禁剧烈运动防意外扭伤骨折；③ 预防感冒，体检前3天慎服感冒药/抗生素；④ 若对某项当日结果有疑问，可按规定申请复检。</li>\n    </ul>\n  </div>\n\n  <div class=\"int-card\">\n    <div class=\"int-card-head\">\n      <span class=\"int-num\">政审与考察</span>\n      <h3>政审材料清单、个人自查与单位实地考察应对（D2G 原文）</h3>\n    </div>\n    <ul>\n      <li><strong>考生需准备的 6 项核心材料</strong>：① 个人征信报告（中国人民银行征信中心或自助机打印，<strong>切勿网贷逾期！</strong>）；② 户籍地派出所出具的无犯罪记录证明；③ 学历学位证书原件及学信网认证；④ 个人人事档案（确保高中起学籍档案、团员党员材料、<strong>西部计划志愿服务鉴定表</strong>齐全且无涂改）；⑤ 个人简历与近三年自我总结鉴定；⑥ 服务单位出具的现实表现材料。</li>\n      <li><strong>实地考察流程（《考察的最佳实践.md》）</strong>：招录单位人事部门派出 2 名考察组成员，赴你当前服务单位（或毕业院校/社区）与分管领导、同事谈话，了解政治素质、日常工作作风与群众评价，并与你本人单独面谈。</li>\n      <li><strong>应对八字原则</strong>：<strong>“真诚大方，积极配合”</strong>——问什么如实答什么，提前跟服务单位分管领导和团委老师沟通好考察时间，准备好办公台账与服务成果展示即可稳稳过关！</li>\n    </ul>\n  </div>\n</div>\n"};
